let queued=false;
/* The route renderer and this controller both write inside #golf-outing.
   Mark our finished view so the observer does not treat its own paint as a
   fresh route render and repaint forever. */
function needsPaint(){const r=route();if(!r.golf||!r.id)return false;const root=document.querySelector("#golf-outing");return Boolean(root&&!root.querySelector("[data-gqm-root]"));}
function schedule(){if(queued)return;queued=true;queueMicrotask(async()=>{try{await paint()}finally{queued=false}})}
new MutationObserver(()=>{if(needsPaint())schedule()}).observe(document.documentElement,{childList:true,subtree:true});
window.addEventListener("hashchange",schedule);
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",schedule);else schedule();
